
import { NextResponse } from "next/server";
import { z } from "zod";
import { getSupabase } from "@/lib/supabase";

export const runtime = "nodejs";

const schema = z.object({
  studentName: z.string().trim().min(1).max(60),
  email: z.string().email().max(150),
  phone: z.string().max(20).optional(),
  city: z.string().trim().min(1).max(80),
  stream: z.string().max(30),
  interests: z.array(z.string().max(60)).min(1).max(5),
  experience: z.string().max(60),
  favoriteSubject: z.string().max(60),
  careerGoal: z.string().max(100),
  language: z.string().max(30),
  guardianConsent: z.boolean().default(false)
});

export async function POST(request: Request) {
  try {
    // Admin authentication
    const key = request.headers.get("x-admin-key");
    const expectedKey = process.env.ADMIN_ACCESS_KEY;

    if (!expectedKey || key !== expectedKey) {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 401 }
      );
    }

    const parsed = schema.safeParse(await request.json());

    if (!parsed.success) {
      return NextResponse.json(
        { error: "Please enter valid student details." },
        { status: 400 }
      );
    }

    const student = parsed.data;

    const score =
      (student.interests.length >= 2 ? 20 : 10) +
      20 +
      10 +
      15 +
      15;

    const category =
      score >= 80 ? "high-intent" :
      score >= 50 ? "medium-intent" :
      "early-interest";

    const supabase = getSupabase();

    const { data, error } = await supabase
      .from("pathfinder_leads")
      .insert({
        student_name: student.studentName,
        email: student.email,
        phone: student.phone || null,
        city: student.city,
        stream: student.stream,
        interests: student.interests,
        experience: student.experience,
        favorite_subject: student.favoriteSubject,
        career_goal: student.careerGoal,
        language: student.language,
        consent: true,
        guardian_consent: student.guardianConsent,
        lead_score: score,
        lead_category: category,
        report: null
      })
      .select()
      .single();

    if (error) {
      console.error("Student insertion error:", error.message);
      throw error;
    }

    return NextResponse.json({
      success: true,
      message: "Student added successfully.",
      student: data
    });

  } catch (error) {
    console.error("Add student API error:", error);

    return NextResponse.json(
      { error: "Unable to add student." },
      { status: 500 }
    );
  }
}
